// ---- Benchmarks in Rust ----
// Add to Cargo.toml:
// [dev-dependencies]
// criterion = { version = "0.5", features = ["html_reports"] }

// ---- Code to benchmark ----
fn fibonacci_recursive(n: u32) -> u64 {
    if n <= 1 {
        1
    } else {
        fibonacci_recursive(n - 1) + fibonacci_recursive(n - 2)
    }
}

fn fibonacci_iterative(n: u32) -> u64 {
    match n {
        0 => 1,
        1 => 1,
        _ => {
            let mut a = 1;
            let mut b = 1;
            for _ in 2..=n {
                let c = a + b;
                a = b;
                b = c;
            }
            b
        }
    }
}

fn sum_squares(n: u32) -> u32 {
    (0..=n).map(|x| x * x).sum()
}

fn sum_squares_loop(n: u32) -> u32 {
    let mut sum = 0;
    for i in 0..=n {
        sum += i * i;
    }
    sum
}

