// ---- Running benchmarks ----
// cargo bench

// ---- Simple benchmark with std::time ----
use std::time::Instant;

fn main() {
    println!("=== Simple Benchmarks ===");

    // Benchmark recursive
    let start = Instant::now();
    let result = fibonacci_recursive(30);
    let duration = start.elapsed();
    println!("Recursive(30): {} in {:?}", result, duration);

    // Benchmark iterative
    let start = Instant::now();
    let result = fibonacci_iterative(30);
    let duration = start.elapsed();
    println!("Iterative(30): {} in {:?}", result, duration);

    // Compare methods
    let start = Instant::now();
    for _ in 0..1000 {
        let _ = sum_squares(100);
    }
    let duration1 = start.elapsed();

    let start = Instant::now();
    for _ in 0..1000 {
        let _ = sum_squares_loop(100);
    }
    let duration2 = start.elapsed();

    println!("sum_squares: {:?}", duration1);
    println!("sum_squares_loop: {:?}", duration2);
    println!("Loop is faster by: {:?}", duration1 - duration2);
}

